// API корзины — добавление товара (получаем warehouse_product UUID для заказа)

import { getAuthHeaders } from "../auth/authApi";

const CART_API_URL = "http://62.84.115.11:8000/api/cart/";

export interface AddToCartRequest {
  product_slug: string;
  color_slug: string;
  size_slug: string;
}

export interface AddToCartResponse {
  id: string;
  user: number;
  warehouse_product: string;
  quantity: number;
}

/**
 * Добавляет товар в корзину на бэкенде и возвращает warehouse_product (UUID) для использования в заказе.
 */
export const addToCart = async (
  productSlug: string,
  colorSlug: string,
  sizeSlug: string
): Promise<AddToCartResponse> => {
  const body: AddToCartRequest = {
    product_slug: productSlug,
    color_slug: colorSlug,
    size_slug: sizeSlug,
  };

  const response = await fetch(CART_API_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getAuthHeaders(),
    },
    credentials: "include",
    mode: "cors",
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    let message = errorText || `${response.status} ${response.statusText}`;
    try {
      const errJson = JSON.parse(errorText);
      if (errJson.detail) message = typeof errJson.detail === "string" ? errJson.detail : JSON.stringify(errJson.detail);
    } catch {}
    throw new Error(`Ошибка добавления в корзину: ${message}`);
  }

  return response.json();
};
